import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"TextSense: ML That Ships Like a Real Service","description":"Why most NLP repos are notebooks — and how TextSense wraps a transformer in the operational scaffolding a real service needs.","frontmatter":{"title":"TextSense: ML That Ships Like a Real Service","description":"Why most NLP repos are notebooks — and how TextSense wraps a transformer in the operational scaffolding a real service needs."},"headers":[],"relativePath":"en/vibe-stories/story-3/index.md","filePath":"en/vibe-stories/story-3/index.md"}`),a={name:`en/vibe-stories/story-3/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="textsense-ml-that-ships-like-a-real-service" tabindex="-1">TextSense: ML That Ships Like a Real Service <a class="header-anchor" href="#textsense-ml-that-ships-like-a-real-service" aria-label="Permalink to “TextSense: ML That Ships Like a Real Service”">​</a></h1><p>Most &quot;NLP API&quot; repos you find are a notebook behind a Flask <code>if __name__ == &quot;__main__&quot;</code>. They die the moment someone asks a production question: what are the metrics? what happens when the model can&#39;t load? how do you scale it? <strong><a href="https://github.com/Godde3s/textsense" target="_blank" rel="noreferrer">TextSense</a></strong> is my answer — an ML model wrapped in the operational scaffolding a real service needs.</p><h2 id="the-engineering-bet" tabindex="-1">The engineering bet <a class="header-anchor" href="#the-engineering-bet" aria-label="Permalink to “The engineering bet”">​</a></h2><p>Sentiment and intent analysis over HTTP, with a transformer backend (DistilBERT SST-2). That part is table stakes. The bet was in everything around the model:</p><ul><li><strong>Graceful degradation</strong> — a <code>ModelProvider</code> pattern tries <code>transformers</code> first; if weights are unavailable, a deterministic lexicon engine answers with the <em>identical API contract</em>. The service never hard-fails because a model didn&#39;t download.</li><li><strong>Latency discipline</strong> — warm-up inference at startup, a batch endpoint with internal micro-batching, and caching so repeated inputs don&#39;t recompute.</li><li><strong>Observability from day one</strong> — Prometheus-format <code>/metrics</code> with request counters, latency histograms, cache hits and the active model backend as a label.</li></ul><h2 id="honest-responses" tabindex="-1">Honest responses <a class="header-anchor" href="#honest-responses" aria-label="Permalink to “Honest responses”">​</a></h2><p>Every response carries the model id that produced it — <code>distilbert-sst2</code> or <code>lexicon-v1</code> — because a score without provenance is a guess pretending to be data. Optional API-key auth, payload size caps and input sanitization round out the surface.</p><h2 id="what-it-proves" tabindex="-1">What it proves <a class="header-anchor" href="#what-it-proves" aria-label="Permalink to “What it proves”">​</a></h2><p>The 15+ pytest cases run offline in under five seconds against the lexicon backend — no GPU, no gigabytes of downloads, CI green on every push. TextSense is the rare ML repo written from the backend engineer&#39;s chair: model choices matter less than the contract, the metrics and the failure story. That is the mindset I bring to any AI-adjacent team — the model is a component, the service is the product.</p>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};